package com.bank.routing.service;

import java.util.logging.Logger;

// Detects a valid loop in a circular routing ring (same direction, length > 1).
public class RingLoopDetector {
    private static final Logger log = Logger.getLogger(RingLoopDetector.class.getName());

    public boolean hasLoop(int[] ring) {
        int n = ring.length;
        for (int start = 0; start < n; start++) {
            boolean forward = ring[start] > 0; // fix the direction for this path
            int slow = start, fast = start;

            while (true) {
                slow = nextIndex(ring, slow, forward);
                if (slow == -1) break;            // direction flipped → invalid

                fast = nextIndex(ring, fast, forward);
                if (fast != -1) fast = nextIndex(ring, fast, forward);
                if (fast == -1) break;

                if (slow == fast) {
                    log.severe(() -> "Routing loop detected starting path.");
                    return true;                  // slow == fast and length > 1
                }
            }
        }
        log.info("No valid routing loop.");
        return false;
    }

    // Returns the next index, or -1 if the move is invalid (direction flip or self-loop).
    private int nextIndex(int[] ring, int i, boolean forward) {
        boolean dir = ring[i] > 0;
        if (dir != forward) return -1;            // direction must stay consistent
        int n = ring.length;
        int next = ((i + ring[i]) % n + n) % n;   // safe modular jump
        if (next == i) return -1;                 // single-element self-loop disallowed
        return next;
    }
}
