package com.bank.routing;

import com.bank.routing.service.RingLoopDetector;
import java.util.Arrays;
import java.util.logging.Logger;

public class RingLoopDemo {
    private static final Logger log = Logger.getLogger(RingLoopDemo.class.getName());

    public static void main(String[] args) {
        // Forward-jumping ring that forms a loop.
        int[] ring = {2, -1, 1, 2, 2};
        log.info(() -> "Ring: " + Arrays.toString(ring));

        RingLoopDetector detector = new RingLoopDetector();
        boolean loop = detector.hasLoop(ring);

        log.info(() -> "Ring has a valid routing loop: " + loop);
    }
}
